(6990247,"سگنیچر اسکیلیٹ سپر","باربرا سیلگ براؤن ایسی ورسٹائل ترکیبیں بنانا پسند کرتی ہیں جنہیں آپ اپنے خاندان کی پسند کے مطابق ڈھال سکیں۔ اس بنیادی تصور کو استعمال کریں اور ہر بار مختلف ذائقے کے لیے سبزیاں اور مسالے بدلتے رہیں۔ یہ اس لیے بھی بہترین ہے کہ یہ ایک ہی برتن میں بننے والی ڈش ہے۔ باربرا ٹرکی کے کیمے یا بائسن کے کیمے کے ساتھ بھی آزمانے کا مشورہ دیتی ہیں، جس میں سیر شدہ چکنائی تقریباً نہیں ہوتی۔","6","1 ½ کپ",
["1 چائے کا چمچ ایکسٹرا ورجن زیتون کا تیل","1 پاؤنڈ دبلا گائے کا کیمہ (3% چکنائی)","1 کپ پیاز (کٹی ہوئی)","2 پھانک لہسن (باریک کٹا ہوا)","4 کپ منجمد ملی جلی سبزیاں","2 چائے کے چمچ توگاراشی (جاپانی مرچوں کا مرکب)","3 کپ انڈے والے نوڈلز (کچے)","4 کپ گائے کے گوشت کا شوربہ (کم سوڈیم)","1 کپ پانی"],
["زیتون کا تیل ایک بڑی ساتے پین یا کڑاہی میں ڈالیں۔ کیمہ، پیاز اور لہسن ڈال کر کیمے کے بھورا ہونے تک پکائیں۔","سبزیاں اور مسالا ڈال کر اچھی طرح ملائیں۔ نوڈلز ڈال کر اچھی طرح ملائیں۔ شوربہ اور اتنا پانی ڈالیں جو سب کچھ ڈھانپ لے۔","ابال آنے دیں۔ آنچ درمیانی کر دیں اور نوڈلز کے نرم ہونے تک تقریباً 15 منٹ پکائیں۔"],[],[]),
(6990463,"گلوٹن سے پاک انگلش مفن","گلوٹن سے پاک انگلش مفن کی غذائی معلومات","1","1 پورا مفن",["1 پورا گلوٹن سے پاک انگلش مفن"],[],[],[]),
(6991688,"ساتے کی ہوئی ساگ پات کے ساتھ پوچڈ انڈے","یہ رنگین ناشتہ آپ کے دن کی صحت مند شروعات ہے! ملے جلے ساگ پات فائبر اور غذائی اجزاء فراہم کرتے ہیں، جو ذیابیطس کے لیے موزوں ایسا کھانا بناتے ہیں جسے کھا کر آپ اچھا محسوس کریں گے۔","2","1/2 ساگ پات + 1 انڈا + 1/2 سلائس ٹوسٹ",
["1 کھانے کا چمچ سفید سرکہ","2 بڑے انڈے","1 کھانے کا چمچ کینولا تیل","1 چھوٹی پیاز (باریک کٹی ہوئی)","2 پھانک لہسن (باریک کٹا ہوا)","4 کپ ملے جلے ساگ پات (جیسے پالک، کیل، سوئس چارڈ؛ کٹے ہوئے)","1/4 چائے کا چمچ نمک","1/2 چائے کا چمچ کالی مرچ","2 سلائس پورے اناج کی ڈبل روٹی (ٹوسٹ کیے ہوئے، آدھے کٹے ہوئے)"],
["ایک چوڑے، اتھلے برتن میں پانی بھر کر ہلکی ابال پر لائیں۔ پانی میں تھوڑا سا سرکہ ڈالیں۔","ہر انڈے کو ایک چھوٹے پیالے میں توڑ لیں۔","ہر انڈے کو ایک ایک کر کے احتیاط سے ابلتے پانی میں پھسلا دیں۔ بہتی زردی کے لیے 3–4 منٹ پوچ کریں، یا زردی کو زیادہ سخت کرنے کے لیے زیادہ دیر پکائیں۔","انڈے پوچ ہو رہے ہوں تو اسی دوران ایک الگ کڑاہی میں درمیانی آنچ پر تیل گرم کریں۔","کٹی ہوئی پیاز ڈال کر نرم ہونے تک، تقریباً 5 منٹ پکائیں۔","باریک کٹا لہسن ڈالیں اور مزید 30 سیکنڈ پکائیں۔","کٹے ہوئے ملے جلے ساگ پات کڑاہی میں ڈالیں اور مرجھانے تک ساتے کریں۔","ساگ پات پر نمک اور کالی مرچ ڈالیں۔","پوچ کیے ہوئے انڈوں کو سوراخ دار چمچ سے پانی سے نکالیں اور اضافی پانی نکالنے کے لیے کاغذی تولیے بچھی پلیٹ پر رکھیں۔","پوچ کیے ہوئے انڈوں کو ساتے کیے ہوئے ساگ پات کے بستر پر رکھ کر پیش کریں اور ساتھ میں پورے اناج کی ڈبل روٹی رکھیں۔"],[],[]),
(6991775,"چٹپٹی بروکولینی اور لہسن","بروکولینی ذائقے اور ساخت میں بروکولی جیسی ہے، لیکن اس کے ڈنٹھل لمبے اور پتلے اور پھول چھوٹے ہوتے ہیں۔ یہ سادہ، ذائقہ دار ترکیب بروکولینی تیار کرنے کا تیز اور آسان طریقہ ہے۔ آپ اسے اتنی دیر میں تیار کر سکتے ہیں جتنی دیر میں آپ کی مرکزی ڈش پکتی ہے۔ اگر آپ کو بروکولینی نہ ملے تو آپ آسانی سے بروکولی استعمال کر سکتے ہیں۔","8","1/2 کپ",
["1 کھانے کا چمچ زیتون کا تیل","4 پھانک لہسن (پتلے کٹے ہوئے)","2 پاؤنڈ بروکولینی (ڈنٹھل کٹے ہوئے)","1/4 کپ کم سوڈیم سبزیوں کا شوربہ","1 چٹکی کٹی ہوئی لال مرچ کے فلیکس","1 1/2 کھانے کے چمچ لیموں کا رس","2 چائے کے چمچ تازہ لیموں کا چھلکا"],
["ہلکی درمیانی آنچ پر تیل گرم کریں۔ لہسن ڈال کر تقریباً 5 سے 6 منٹ ساتے کریں، یا بس لہسن کے بھورا ہونا شروع ہونے تک۔","بروکولینی، شوربہ اور کٹی ہوئی لال مرچ ڈالیں۔ برتن ڈھانپ دیں اور درمیانی تیز آنچ پر بھاپ میں پکنے دیں جب تک بروکولینی چمکدار ہری اور نرم نہ ہو جائے، تقریباً 5 سے 6 منٹ۔","لیموں کا رس اور چھلکا ڈالیں اور فوراً پیش کریں۔"],[],[]),
(6992159,"بحیرہ روم طرز کا چکن پیٹا","بچے ہوئے چکن کو اس سادہ اور مزیدار سینڈوچ میں استعمال کریں! یہ گھر سے کام کرنے کے دوران جلدی اور آسانی سے بننے والا دوپہر کا کھانا، یا مصروف ہفتے کی رات کا کھانا ہے۔ اگر آپ کے پاس تزاتزیکی ساس نہ ہو تو آپ سادہ یونانی دہی استعمال کر سکتے ہیں۔ دگنا لطف: مزید ذائقے کے لیے ہماری Greek Yogurt-Marinated Chicken ترکیب کا بچا ہوا چکن استعمال کریں!","4","1 پیٹا پاکٹ (جس میں ½ پیٹا روٹی، 2 ½ اونس چکن، 2 کھانے کے چمچ چٹنی، ½ کپ سبزیاں اور 2 کھانے کے چمچ بادام شامل ہیں)",
["2 کپ پکا ہوا چکن (چوکور ٹکڑوں میں)","1/2 کپ کم چکنائی والی تزاتزیکی ساس (یا بغیر چکنائی کا سادہ یونانی دہی)","2 عدد پورے اناج کے پاکٹ طرز کے پیٹا (آدھے کاٹ کر 4 پیٹا پاکٹس بنا لیں)","1 کپ کھیرا (کٹا ہوا)","1 کپ ٹماٹر (کٹے ہوئے)","1/2 کپ خشک بھنے ہوئے بادام (بغیر نمک کے، قتلے کیے ہوئے)"],
["ایک درمیانے مکسنگ پیالے میں چکن اور تزاتزیکی ساس کو ملا لیں۔ ہر پیٹا پاکٹ میں چکن کے مرکب کا ½ کپ بھر دیں۔","ہر بھرے ہوئے پیٹا پاکٹ پر ¼ کپ کھیرا، ¼ کپ ٹماٹر اور 2 کھانے کے چمچ بادام کے قتلے ڈالیں۔"],[],[]),
(6992179,"پارمیزان کرسٹڈ چکن","ذائقہ دار اور ہمہ جہت چکن کی ترکیب، اسے سبزیوں کے ساتھ مرکزی ڈش کے طور پر یا سلاد پر ڈال کر پیش کریں۔ یہ بچوں کے لیے بھی موزوں ہے اور کسی بھی منجمد چکن نگٹ سے کہیں زیادہ صحت بخش ہے۔","6","2 چکن اسٹرپس",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1/2 کپ مکئی کا دلیہ (کارن میل)","1/3 کپ پارمیزان پنیر (تازہ کدوکش کیا ہوا)","1/2 چائے کا چمچ لہسن پاؤڈر","1/4 چائے کا چمچ کالی مرچ","3 بڑے انڈوں کی سفیدی","1 1/2 پاؤنڈ بغیر ہڈی اور بغیر کھال کی چکن کی چھاتی (12 پتلی پٹیوں میں کٹی ہوئی)"],
["اوون کو 425 ڈگری F پر پہلے سے گرم کریں۔ بیکنگ ٹرے پر کوکنگ اسپرے کریں۔","ایک اتھلی ڈش میں مکئی کا دلیہ، پارمیزان پنیر، لہسن پاؤڈر اور کالی مرچ ملا لیں۔","ایک اور اتھلی بیکنگ ڈش میں انڈوں کی سفیدی پھینٹ لیں۔","چکن کی پٹی کو انڈے کے مرکب میں ڈبوئیں اور پھر مکئی کے مرکب میں اچھی طرح لپیٹ دیں۔ اچھی طرح کوٹنگ کر کے بیکنگ ٹرے پر رکھیں۔ باقی تمام چکن کی پٹیوں کے لیے یہی عمل دہرائیں۔","چکن کی پٹیوں پر کوکنگ اسپرے کریں۔ 15-20 منٹ یا پکنے تک بیک کریں؛ پکانے کے وقت کے آدھے حصے میں چکن کے ٹکڑے پلٹ دیں۔"],[],[]),
(6992930,"پیسٹو ڈیولڈ ایگز","پیسٹو ڈیولڈ ایگز کلاسک ترکیب کا ایک ذائقہ دار اور نفیس انداز ہیں۔ پیسٹو، مایونیز اور ڈیجون سرسوں کا امتزاج ایک کریمی اور چٹپٹی بھرائی بناتا ہے جو ابلے ہوئے انڈوں کی قدرتی لذت کے ساتھ خوب جچتی ہے۔ یہ ڈیولڈ ایگز پارٹیوں کے لیے بہترین اپیٹائزر ہیں یا برنچ کے دسترخوان میں ایک مزیدار اضافہ۔","8","2 آدھے",
["8 بڑے انڈے","1/4 کپ ہلکی مایونیز","2 کھانے کے چمچ بوتل بند پیسٹو ساس","1 چائے کا چمچ ڈیجون سرسوں","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["انڈوں کو ایک دیگچی میں ایک تہہ میں رکھیں اور پانی سے ڈھانپ دیں۔ پانی کو ابال لائیں، پھر آنچ دھیمی کر کے ڈھانپ دیں اور 10–12 منٹ تک پکائیں۔","ابلے ہوئے انڈوں کو ٹھنڈا کرنے کے لیے برف کے پانی کے ٹب میں منتقل کریں۔","انڈے ٹھنڈے ہو جائیں تو انہیں چھیل لیں اور لمبائی میں آدھا کاٹ لیں۔ زردیاں نکال کر ایک پیالے میں رکھ لیں۔","زردیوں والے پیالے میں مایونیز، تیار تلسی پیسٹو، ڈیجون سرسوں، نمک اور کالی مرچ ڈالیں۔ ان اجزاء کو ہموار ہونے تک مسل کر ملا لیں۔","پیسٹو کی بھرائی کو چمچ یا پائپنگ بیگ سے کھوکھلی انڈے کی سفیدیوں میں بھر دیں۔","ڈیولڈ ایگز کو پیش کرنے سے پہلے کم از کم 30 منٹ فریج میں ٹھنڈا کریں۔"],[],[]),
